@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-description">@TruncatedDescription</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnClick { get; set; }

    private string TruncatedDescription =>
        Channel.Description.Length > 40
            ? Channel.Description[..40] + "…"
            : Channel.Description;
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<aside class="channel-sidebar">
    <h3 class="sidebar-title">Channels</h3>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</aside>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = [];
    [Parameter] public int? ActiveChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="reaction-bar">
    @foreach (var reaction in Reactions)
    {
        <span class="reaction-badge" @onclick="() => OnReactionClicked.InvokeAsync(reaction.Emoji)"
              title="@string.Join(", ", reaction.Users)">
            @reaction.Emoji @reaction.Users.Count
        </span>
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Reaction> Reactions { get; set; } = [];
    [Parameter] public EventCallback<string> OnReactionClicked { get; set; }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="emoji-picker">
    @foreach (var emoji in CommonEmojis)
    {
        <button class="emoji-btn" @onclick="() => OnEmojiSelected.InvokeAsync(emoji)">@emoji</button>
    }
</div>

@code {
    [Parameter] public EventCallback<string> OnEmojiSelected { get; set; }

    private static readonly string[] CommonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "🔥"];
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="message-bubble" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <ReactionBar Reactions="Message.Reactions" OnReactionClicked="HandleReaction" />
    }

    @if (ThreadInfo is not null)
    {
        <button class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ThreadInfo.ReplyCount replies
        </button>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">Reply</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker">React</button>
        </div>
    }

    @if (showEmojiPicker)
    {
        <EmojiPicker OnEmojiSelected="HandleEmojiSelected" />
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public ThreadSummary? ThreadInfo { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }

    private bool showActions;
    private bool showEmojiPicker;

    private void ToggleEmojiPicker() => showEmojiPicker = !showEmojiPicker;

    private async Task HandleEmojiSelected(string emoji)
    {
        showEmojiPicker = false;
        await OnReaction.InvokeAsync((Message.Id, emoji));
    }

    private async Task HandleReaction(string emoji)
    {
        await OnReaction.InvokeAsync((Message.Id, emoji));
    }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoadingOlder)
    {
        <div class="loading-indicator">Loading older messages…</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ThreadInfo="GetThreadInfo(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReaction="OnReaction" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }

    private ThreadSummary? GetThreadInfo(int messageId) =>
        ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId);

    private async Task HandleScroll(EventArgs e)
    {
        // Triggered when user scrolls to top to load older messages
        await OnLoadOlder.InvokeAsync();
    }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="message-header-bar">
    <h2 class="channel-title"># @ChannelName</h2>
    <p class="channel-desc">@Description</p>
</div>

@code {
    [Parameter, EditorRequired] public string ChannelName { get; set; } = "";
    [Parameter] public string Description { get; set; } = "";
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<div class="message-input">
    <textarea @bind="text" @bind:event="oninput" placeholder="@Placeholder"
              @onkeydown="HandleKeyDown" rows="2"></textarea>
    <button class="send-btn" @onclick="Send" disabled="@string.IsNullOrWhiteSpace(text)">@ButtonLabel</button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message…";
    [Parameter] public string ButtonLabel { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string text = "";

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(text)) return;
        var content = text.Trim();
        text = "";
        await OnSend.InvokeAsync(content);
    }

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e is { Key: "Enter", ShiftKey: false })
        {
            await Send();
        }
    }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<section class="message-area">
    @if (Channel is not null)
    {
        <MessageHeader ChannelName="@Channel.Name" Description="@Channel.Description" />
        <MessageList Messages="Messages"
                     ThreadSummaries="ThreadSummaries"
                     IsLoadingOlder="IsLoadingOlder"
                     OnLoadOlder="OnLoadOlder"
                     OnOpenThread="OnOpenThread"
                     OnReaction="OnReaction" />
        <MessageInput Placeholder="@($"Message #{Channel.Name}")" OnSend="OnSendMessage" />
    }
    else
    {
        <div class="no-channel-selected">Select a channel to start chatting</div>
    }
</section>

@code {
    [Parameter] public Channel? Channel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = [];
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = [];
    [Parameter] public bool IsLoadingOlder { get; set; }
    [Parameter] public EventCallback OnLoadOlder { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReaction { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

@namespace sv_f04dd4eda45742c9ae1a098b7faeb4be.Components.Pages.Chat

<aside class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>
    <div class="thread-original">
        <span class="message-author">@RootMessage.Author</span>
        <p>@RootMessage.Content</p>
    </div>
    <div class="thread-replies">
        @foreach (var reply in Replies)
        {
            <div class="thread-reply">
                <div class="message-header">
                    <span class="message-author">@reply.Author</span>
                    <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                </div>
                <div class="message-content">@reply.Content</div>
            </div>
        }
    </div>
    <MessageInput Placeholder="Reply in thread…" ButtonLabel="Reply" OnSend="OnSendReply" />
</aside>

@code {
    [Parameter, EditorRequired] public Message RootMessage { get; set; } = default!;
    [Parameter] public List<Message> Replies { get; set; } = [];
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

